const upsertOwnerNotificationBinding = `-- name: UpsertOwnerNotificationBinding :one
INSERT INTO owner_notification_binding (
    workspace_id, recipient_id, destination_key, destination_fingerprint,
    delivery_mode, enabled
) VALUES (
    $1, $2, $3, $4,
    $5, $6
)
ON CONFLICT (workspace_id) DO UPDATE
SET recipient_id = EXCLUDED.recipient_id,
    destination_key = EXCLUDED.destination_key,
    destination_fingerprint = EXCLUDED.destination_fingerprint,
    delivery_mode = EXCLUDED.delivery_mode,
    enabled = EXCLUDED.enabled,
    updated_at = now()
RETURNING workspace_id, recipient_id, destination_key, destination_fingerprint, delivery_mode, enabled, created_at, updated_at
`

